@using sv_a650f1ca46d2402ba769b2d0ca261221.Services
@inject WarehouseState Warehouse
@implements IDisposable
@rendermode InteractiveServer

<div class="d-flex align-items-center gap-2">
    <label class="form-label mb-0 text-nowrap" for="warehouse-select">
        <strong>Warehouse:</strong>
    </label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            style="width: auto;"
            value="@Warehouse.SelectedWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseState.AvailableWarehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        Warehouse.OnChange += StateHasChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            Warehouse.SetWarehouse(newId);
        }
    }

    public void Dispose()
    {
        Warehouse.OnChange -= StateHasChanged;
    }
}

@using sv_a650f1ca46d2402ba769b2d0ca261221.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-auto">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-auto">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Wrap in InvokeAsync because the event may fire from a timer callback
        // on a non-Blazor thread.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

