    {
        var count = await AlertService.GetLowStockCountAsync(Warehouse.SelectedWarehouseId);
        _lastPollTime = DateTime.Now;
        // Publish to ALL subscribers (sidebar badge, other components).
        AlertService.UpdateAlertCount(count);
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
        Warehouse.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

